-- ParkIt core schema (DATABASE_DESIGN.md v2.1, section 9).
-- Copied verbatim from the approved DDL baseline. Do not edit after it has been applied;
-- add a new versioned migration instead.

CREATE TABLE users (
  user_id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name          VARCHAR(100) NOT NULL,
  email         VARCHAR(150) NOT NULL,
  password_hash VARCHAR(100) NOT NULL,
  phone         VARCHAR(20)  NOT NULL,
  role          VARCHAR(20)  NOT NULL DEFAULT 'CUSTOMER' CHECK (role IN ('CUSTOMER','ADMIN')),
  is_active     BOOLEAN      NOT NULL DEFAULT TRUE,
  created_at    TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX ux_users_email_lower ON users (lower(email));

CREATE TABLE vehicles (
  vehicle_id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id             BIGINT NOT NULL REFERENCES users(user_id),
  registration_number VARCHAR(20) NOT NULL UNIQUE
                      CHECK (registration_number = upper(registration_number)
                             AND registration_number !~ '[[:space:]-]'),
  vehicle_type        VARCHAR(10) NOT NULL CHECK (vehicle_type IN ('CAR','BIKE')),
  is_electric         BOOLEAN NOT NULL DEFAULT FALSE,
  description         VARCHAR(150),
  is_active           BOOLEAN NOT NULL DEFAULT TRUE,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_vehicle_owner UNIQUE (vehicle_id, user_id),
  CONSTRAINT ck_electric_car CHECK (NOT is_electric OR vehicle_type = 'CAR')
);
CREATE INDEX ix_vehicles_user ON vehicles (user_id);

CREATE TABLE parking_slots (
  slot_id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slot_number        VARCHAR(20) NOT NULL UNIQUE,
  sort_order         INTEGER     NOT NULL UNIQUE CHECK (sort_order > 0),
  vehicle_type       VARCHAR(10) NOT NULL CHECK (vehicle_type IN ('CAR','BIKE')),
  operational_status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE'
                     CHECK (operational_status IN ('ACTIVE','INACTIVE')),
  created_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX ix_slots_category ON parking_slots (vehicle_type, operational_status, slot_id);

CREATE TABLE bookings (
  booking_id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_reference    VARCHAR(32) NOT NULL UNIQUE,
  user_id              BIGINT NOT NULL REFERENCES users(user_id),
  vehicle_id           BIGINT NOT NULL,
  slot_id              BIGINT NOT NULL REFERENCES parking_slots(slot_id),
  created_by_user_id   BIGINT NOT NULL REFERENCES users(user_id),
  scheduled_start      TIMESTAMPTZ NOT NULL,
  scheduled_end        TIMESTAMPTZ NOT NULL,
  hold_expires_at      TIMESTAMPTZ NOT NULL,
  confirmed_at         TIMESTAMPTZ,
  actual_check_in      TIMESTAMPTZ,
  actual_check_out     TIMESTAMPTZ,
  hourly_rate_snapshot NUMERIC(10,2) NOT NULL CHECK (hourly_rate_snapshot > 0),
  daily_rate_snapshot  NUMERIC(10,2) NOT NULL CHECK (daily_rate_snapshot > 0),
  booking_amount       NUMERIC(10,2) NOT NULL CHECK (booking_amount > 0),
  overstay_amount      NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (overstay_amount >= 0),
  overstay_minutes     INTEGER NOT NULL DEFAULT 0 CHECK (overstay_minutes >= 0),
  reassignment_wait_until TIMESTAMPTZ,
  booking_status       VARCHAR(20) NOT NULL CHECK (booking_status IN
                       ('PENDING_PAYMENT','CONFIRMED','CHECKED_IN','COMPLETED',
                        'CANCELLED','PAYMENT_EXPIRED','NO_SHOW')),
  cancelled_at         TIMESTAMPTZ,
  cancelled_by_user_id BIGINT REFERENCES users(user_id),
  cancellation_reason  VARCHAR(255),
  created_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  version              BIGINT NOT NULL DEFAULT 0,

  CONSTRAINT fk_booking_vehicle_owner FOREIGN KEY (vehicle_id, user_id)
             REFERENCES vehicles (vehicle_id, user_id),
  CONSTRAINT ck_interval CHECK (scheduled_end > scheduled_start),
  CONSTRAINT ck_duration CHECK (scheduled_end - scheduled_start
             BETWEEN INTERVAL '1 hour' AND INTERVAL '7 days'),
  -- 15-minute grid (UTC+05:30 keeps local and UTC quarter-hours aligned)
  CONSTRAINT ck_grid CHECK (EXTRACT(EPOCH FROM scheduled_start)::BIGINT % 900 = 0
                        AND EXTRACT(EPOCH FROM scheduled_end)::BIGINT % 900 = 0),
  CONSTRAINT ck_checkout_order CHECK (actual_check_out IS NULL
             OR (actual_check_in IS NOT NULL AND actual_check_out >= actual_check_in)),
  CONSTRAINT ck_confirmed_at CHECK (
             (booking_status IN ('CONFIRMED','CHECKED_IN','COMPLETED','NO_SHOW')) <= (confirmed_at IS NOT NULL)
         AND (booking_status IN ('PENDING_PAYMENT','PAYMENT_EXPIRED')) <= (confirmed_at IS NULL)),
  CONSTRAINT ck_check_in CHECK (
             (booking_status IN ('CHECKED_IN','COMPLETED')) = (actual_check_in IS NOT NULL)),
  CONSTRAINT ck_check_out CHECK (
             (booking_status = 'COMPLETED') = (actual_check_out IS NOT NULL)),
  CONSTRAINT ck_overstay CHECK ((overstay_minutes > 0) = (overstay_amount > 0)
         AND (overstay_minutes = 0 OR booking_status = 'COMPLETED')),
  CONSTRAINT ck_reassign_wait CHECK (reassignment_wait_until IS NULL
             OR booking_status IN ('CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED')),
  CONSTRAINT ck_cancelled CHECK (
             (booking_status = 'CANCELLED') = (cancelled_at IS NOT NULL)
         AND (cancelled_at IS NULL OR cancellation_reason IS NOT NULL)),

  CONSTRAINT ex_slot_overlap EXCLUDE USING gist (
             slot_id WITH =,
             tstzrange(scheduled_start, scheduled_end, '[)') WITH &&)
             WHERE (booking_status IN ('PENDING_PAYMENT','CONFIRMED','CHECKED_IN')),
  CONSTRAINT ex_vehicle_overlap EXCLUDE USING gist (
             vehicle_id WITH =,
             tstzrange(scheduled_start, scheduled_end, '[)') WITH &&)
             WHERE (booking_status IN ('PENDING_PAYMENT','CONFIRMED','CHECKED_IN'))
);
CREATE UNIQUE INDEX ux_one_hold_per_customer ON bookings (user_id)
       WHERE booking_status = 'PENDING_PAYMENT';
CREATE INDEX ix_bookings_user_start  ON bookings (user_id, scheduled_start DESC);
CREATE INDEX ix_bookings_vehicle     ON bookings (vehicle_id);
CREATE INDEX ix_bookings_creator     ON bookings (created_by_user_id);
CREATE INDEX ix_bookings_allocation  ON bookings (slot_id, confirmed_at);
CREATE INDEX ix_bookings_hold_sweep  ON bookings (hold_expires_at)
       WHERE booking_status = 'PENDING_PAYMENT';
CREATE INDEX ix_bookings_noshow_sweep ON bookings (scheduled_start)
       WHERE booking_status = 'CONFIRMED';
CREATE INDEX ix_bookings_checked_in  ON bookings (slot_id)
       WHERE booking_status = 'CHECKED_IN';
CREATE INDEX ix_bookings_status_start ON bookings (booking_status, scheduled_start);

CREATE TABLE payments (
  payment_id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id            BIGINT NOT NULL REFERENCES bookings(booking_id),
  payment_type          VARCHAR(20) NOT NULL CHECK (payment_type IN ('BOOKING','OVERSTAY')),
  payment_method        VARCHAR(20) NOT NULL
                        CHECK (payment_method IN ('ONLINE_SIMULATED','COUNTER_SIMULATED')),
  amount                NUMERIC(10,2) NOT NULL CHECK (amount > 0),
  payment_status        VARCHAR(20) NOT NULL CHECK (payment_status IN ('PENDING','SUCCESS','FAILED')),
  idempotency_key       VARCHAR(80) NOT NULL UNIQUE,
  transaction_reference VARCHAR(60) UNIQUE,
  failure_reason        VARCHAR(255),
  recorded_by_user_id   BIGINT REFERENCES users(user_id),
  created_at            TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  completed_at          TIMESTAMPTZ,
  CONSTRAINT ck_payment_completed CHECK ((payment_status = 'PENDING') = (completed_at IS NULL))
);
CREATE INDEX ix_payments_booking ON payments (booking_id);
CREATE INDEX ix_payments_completed ON payments (completed_at);
CREATE UNIQUE INDEX ux_one_success_per_type ON payments (booking_id, payment_type)
       WHERE payment_status = 'SUCCESS';
CREATE UNIQUE INDEX ux_one_pending_per_type ON payments (booking_id, payment_type)
       WHERE payment_status = 'PENDING';

CREATE TABLE refunds (
  refund_id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  payment_id           BIGINT NOT NULL REFERENCES payments(payment_id),
  amount               NUMERIC(10,2) NOT NULL CHECK (amount > 0),
  refund_status        VARCHAR(20) NOT NULL CHECK (refund_status IN ('PENDING','SUCCESS','FAILED')),
  reason               VARCHAR(255) NOT NULL,
  idempotency_key      VARCHAR(80) NOT NULL UNIQUE,
  refund_reference     VARCHAR(60) UNIQUE,
  failure_reason       VARCHAR(255),
  initiated_by_user_id BIGINT REFERENCES users(user_id),
  created_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  completed_at         TIMESTAMPTZ,
  CONSTRAINT ck_refund_completed CHECK ((refund_status = 'PENDING') = (completed_at IS NULL))
);
CREATE INDEX ix_refunds_payment ON refunds (payment_id);
CREATE INDEX ix_refunds_completed ON refunds (completed_at);
CREATE UNIQUE INDEX ux_one_live_refund ON refunds (payment_id)
       WHERE refund_status IN ('PENDING','SUCCESS');

CREATE TABLE parking_rates (
  rate_id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  vehicle_type       VARCHAR(10) NOT NULL UNIQUE CHECK (vehicle_type IN ('CAR','BIKE')),
  hourly_rate        NUMERIC(10,2) NOT NULL CHECK (hourly_rate > 0),
  daily_rate         NUMERIC(10,2) NOT NULL CHECK (daily_rate > 0),
  updated_by_user_id BIGINT REFERENCES users(user_id),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE slot_blocks (
  block_id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slot_id              BIGINT NOT NULL REFERENCES parking_slots(slot_id),
  start_time           TIMESTAMPTZ NOT NULL,
  end_time             TIMESTAMPTZ NOT NULL,
  reason               VARCHAR(255) NOT NULL,
  created_by_user_id   BIGINT NOT NULL REFERENCES users(user_id),
  created_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  cancelled_at         TIMESTAMPTZ,
  cancelled_by_user_id BIGINT REFERENCES users(user_id),
  CONSTRAINT ck_block_interval CHECK (end_time > start_time),
  CONSTRAINT ck_block_cancel CHECK ((cancelled_at IS NULL) = (cancelled_by_user_id IS NULL))
);
CREATE INDEX ix_blocks_active ON slot_blocks
       USING gist (slot_id, tstzrange(start_time, end_time, '[)'))
       WHERE cancelled_at IS NULL;

CREATE TABLE facility_settings (
  setting_id         SMALLINT PRIMARY KEY CHECK (setting_id = 1),
  facility_name      VARCHAR(150) NOT NULL,
  opening_time       TIME NOT NULL,
  closing_time       TIME NOT NULL,
  open_24_hours      BOOLEAN NOT NULL DEFAULT FALSE,
  timezone           VARCHAR(50) NOT NULL DEFAULT 'Asia/Kolkata' CHECK (timezone = 'Asia/Kolkata'),
  updated_by_user_id BIGINT REFERENCES users(user_id),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_hours CHECK (open_24_hours OR opening_time <> closing_time)
);

CREATE TABLE audit_logs (
  log_id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  actor_type    VARCHAR(10) NOT NULL CHECK (actor_type IN ('USER','SYSTEM')),
  actor_user_id BIGINT REFERENCES users(user_id),
  action        VARCHAR(100) NOT NULL,
  entity_type   VARCHAR(50) NOT NULL,
  entity_id     BIGINT,
  details       JSONB,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT ck_actor CHECK ((actor_type = 'USER') = (actor_user_id IS NOT NULL))
);
CREATE INDEX ix_audit_actor_time ON audit_logs (actor_user_id, created_at);
CREATE INDEX ix_audit_entity     ON audit_logs (entity_type, entity_id);
CREATE INDEX ix_audit_time       ON audit_logs (created_at);
